-- gen594: 45 zone cambiate, 91 tessere
-- 7e6833be15d708af1e782af1cfedeb75 (735662) → be71b7a3bab904ca33e9958ce31b2bc2 (741966)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = 'be71b7a3bab904ca33e9958ce31b2bc2' as combacia
from kv_store where key like 'tmp:gen594:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen594:p%')
where key='app:jsx:src'
  and md5(value) = '7e6833be15d708af1e782af1cfedeb75'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen594:p%') = 'be71b7a3bab904ca33e9958ce31b2bc2';

update kv_store set value = '{"len":741966,"ver":"gen-5.94"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = 'be71b7a3bab904ca33e9958ce31b2bc2';

delete from kv_store where key like 'tmp:gen594:p%';
